<template><section class="jp-script-files">
 <header class="jp-script-toolbar"><span class="jp-eyebrow">NAMESPACE FILES</span><span>{{Object.keys(files).length}} files</span><span class="jp-grow"/><KsButton size="small" @click="openNew"><Plus :size="15"/>新增脚本</KsButton><KsButton size="small" @click="chooseImport"><Upload :size="15"/>导入</KsButton><input ref="fileInput" class="jp-file-input" type="file" accept=".sh,.bash,.py,.txt,.json,.yaml,.yml,.sql,.js,.ps1" multiple aria-label="导入脚本文件" @change="importFiles"/></header>
 <div v-if="error" class="jp-script-alert" role="alert">{{error}}<button @click="error=''">×</button></div>
 <div class="jp-script-body"><aside class="jp-script-tree"><KsInput v-model="search" placeholder="搜索脚本和文件" clearable/><button v-for="path in visiblePaths" :key="path" :class="{active:path===active}" @click="emit('select',path);message=''"><component :is="languageFor(path)==='plaintext'?FileDocumentOutline:CodeTags" :size="16"/><span>{{path}}<small>rev {{files[path].revision||'未保存'}}</small></span><i v-if="files[path].content!==files[path].saved" title="未保存更改"/></button><p v-if="!visiblePaths.length">没有匹配的文件</p><small class="jp-files-scope">当前原型内存<br/>不上传到服务器，刷新不保留</small></aside>
 <main v-if="current" class="jp-script-workspace"><header class="jp-script-filebar"><div><code>{{active}}</code><span :class="['jp-script-dirty',{saved:!dirty}]">{{dirty?'● 未保存':'✓ 已保存到原型'}}</span></div><span class="jp-grow"/><KsButton size="small" @click="download"><Download :size="15"/>下载</KsButton><KsButton size="small" :disabled="!dirty" @click="save"><ContentSaveOutline :size="15"/>保存</KsButton><KsButton size="small" type="primary" :disabled="!canUse||dirty||languageFor(active)==='plaintext'" :title="!canUse?'请先修正Flow YAML':dirty?'请先保存脚本':undefined" @click="useTarget=canReplace?'selected':'new';useOpen=true">在 Flow 中使用</KsButton></header>
  <Suspense><component :is="CodeEditor" :key="active" :source="current.content" :path="active" :language="languageFor(active)" :theme="theme" @change="v=>emit('edit',active,v)" @save="save"/><template #fallback><div class="jp-script-loading">加载 Monaco 脚本编辑器…</div></template></Suspense>
  <footer><span>{{languageFor(active)==='shell'?'Shell':languageFor(active)==='python'?'Python':'Plain text'}} · UTF-8</span><span>{{current.content.split('\n').length}} 行 · {{byteSize}} bytes</span><span class="jp-grow"/><span>{{message||'Ctrl / ⌘ + S 保存脚本'}}</span></footer>
 </main><div v-else class="jp-script-loading">新增或导入脚本开始编辑</div></div>
 <KsDialog v-model="newOpen" :teleported="false" :appendToBody="false" title="新增脚本" width="510px"><div class="jp-script-dialog"><label>语言<select aria-label="语言" v-model="newKind" @change="newPath='scripts/new_script.'+(newKind==='python'?'py':'sh')"><option value="shell">Shell / Bash</option><option value="python">Python</option></select></label><label>文件路径<KsInput v-model="newPath" placeholder="scripts/check_gpu.py"/></label><p>创建后直接进入 Monaco 在线编辑，保存后可在 Flow 中引用。</p><p v-if="dialogError" role="alert" class="jp-error">{{dialogError}}</p><div class="jp-wizard-footer"><KsButton @click="newOpen=false">取消</KsButton><KsButton type="primary" @click="create">创建并编辑</KsButton></div></div></KsDialog>
 <KsDialog v-model="importOpen" :teleported="false" :appendToBody="false" title="导入脚本文件" width="580px"><div class="jp-script-dialog"><p>文件只读取到当前原型，不执行、不上传。支持文本文件，每份不超过1 MiB。</p><label>目标目录<KsInput v-model="importFolder" placeholder="scripts"/></label><div class="jp-import-list"><label v-for="(f,i) in pendingImports" :key="i"><FileDocumentOutline :size="17"/><span>{{f.name}}<small>{{f.content.length}} characters</small></span><input v-model="f.name" :aria-label="'导入文件名 '+(i+1)"/></label></div><p v-if="dialogError" role="alert" class="jp-error">{{dialogError}}</p><div class="jp-wizard-footer"><KsButton @click="importOpen=false">取消</KsButton><KsButton type="primary" @click="confirmImport">导入并编辑</KsButton></div></div></KsDialog>
 <KsDialog v-model="useOpen" :teleported="false" :appendToBody="false" title="在 Flow 中使用脚本" width="580px"><div class="jp-script-dialog"><code>{{active}} · revision {{current?.revision}}</code><label>引用方式<select aria-label="引用方式" v-model="useMode"><option value="namespace">Namespace 文件引用</option><option value="inline">内联脚本快照</option></select></label><p>{{useMode==='namespace'?'生成 namespaceFiles 与 commands，脚本保留在独立文件中。':'将已保存内容复制到任务的 script 属性；后续文件编辑不会自动覆盖此快照。'}}</p><label>目标任务<select aria-label="目标任务" v-model="useTarget"><option value="new">新增脚本任务</option><option value="selected" :disabled="!canReplace">替换所选脚本任务{{canReplace?'':'（当前节点不是脚本任务）'}}</option></select></label><p class="jp-script-boundary">这里演示 Kestra 任务引用。正式设备执行仍须通过 Keel 的目标、通道、预检与审批；本原型不会执行脚本。</p><div class="jp-wizard-footer"><KsButton @click="useOpen=false">取消</KsButton><KsButton type="primary" @click="emit('use',{path:active,mode:useMode,target:useTarget});useOpen=false;message='脚本已关联到 Flow 草稿'">确认关联</KsButton></div></div></KsDialog>
</section></template>
<script setup lang="ts">
import {computed,defineAsyncComponent,onMounted,ref,watch} from 'vue';
import KsButton from '../../../dev/src/vendor/kestra/design-system/components/Basic/KsButton/KsButton.vue';
import KsInput from '../../../dev/src/vendor/kestra/design-system/components/Form/KsInput.vue';
import KsDialog from '../../../dev/src/vendor/kestra/design-system/components/Feedback/KsDialog.vue';
import Plus from 'vue-material-design-icons/Plus.vue';import Upload from 'vue-material-design-icons/Upload.vue';import Download from 'vue-material-design-icons/Download.vue';import ContentSaveOutline from 'vue-material-design-icons/ContentSaveOutline.vue';import FileDocumentOutline from 'vue-material-design-icons/FileDocumentOutline.vue';import CodeTags from 'vue-material-design-icons/CodeTags.vue';
import {languageFor,scriptTemplate,validatePath,type ScriptFile,type ScriptUse} from './script-files';
const CodeEditor=defineAsyncComponent(()=>import('./ScriptCodeEditor.vue'));
const props=defineProps<{files:Record<string,ScriptFile>;active:string;theme:'dark'|'light';createRequest:number;importRequest:number;canReplace:boolean;canUse:boolean}>();
const emit=defineEmits<{select:[path:string];create:[entries:{path:string;content:string}[]];edit:[path:string,content:string];save:[path:string];use:[value:ScriptUse]}>();
const current=computed(()=>props.files[props.active]);const dirty=computed(()=>current.value?.content!==current.value?.saved);const byteSize=computed(()=>new Blob([current.value?.content||'']).size);
const search=ref(''),error=ref(''),message=ref(''),newOpen=ref(false),newKind=ref('shell'),newPath=ref('scripts/new_script.sh'),dialogError=ref(''),importOpen=ref(false),importFolder=ref('scripts'),pendingImports=ref<{name:string;content:string}[]>([]),fileInput=ref<HTMLInputElement|null>(null),useOpen=ref(false),useMode=ref<'namespace'|'inline'>('namespace'),useTarget=ref<'new'|'selected'>(props.canReplace?'selected':'new');
const visiblePaths=computed(()=>Object.keys(props.files).filter(p=>p.toLowerCase().includes(search.value.toLowerCase())).sort());
function openNew(){newOpen.value=true;dialogError.value=''}
function create(){try{const path=newPath.value.trim();validatePath(path);if(props.files[path])throw Error('该路径已存在，请打开原文件编辑或使用新名称');emit('create',[{path,content:scriptTemplate(newKind.value)}]);newOpen.value=false;message.value='新脚本已创建，编辑后保存'}catch(e){dialogError.value=(e as Error).message}}
function save(){if(!current.value||!dirty.value)return;emit('save',props.active);message.value='已保存到当前原型，不写入服务器'}
function chooseImport(){if(fileInput.value){fileInput.value.value='';fileInput.value.click()}}
async function importFiles(event:Event){error.value='';const selected=Array.from((event.target as HTMLInputElement).files||[]);if(!selected.length)return;try{if(selected.some(f=>f.size>1024*1024))throw Error('文件超过1 MiB，请选择较小的文本脚本');pendingImports.value=await Promise.all(selected.map(async f=>({name:f.name,content:await f.text()})));dialogError.value='';importOpen.value=true}catch(e){error.value=(e as Error).message}}
function confirmImport(){try{const paths=pendingImports.value.map(f=>[importFolder.value.trim().replace(/\/$/,''),f.name.trim()].filter(Boolean).join('/'));for(const path of paths){validatePath(path);if(props.files[path])throw Error(path+' 已存在，请修改导入文件名，避免覆盖')}if(new Set(paths).size!==paths.length)throw Error('导入文件名重复，请修改');emit('create',pendingImports.value.map((f,i)=>({path:paths[i],content:f.content})));emit('select',paths[0]);search.value='';importOpen.value=false;message.value='已导入 '+paths.length+' 个文件，请编辑并保存'}catch(e){dialogError.value=(e as Error).message}}
function download(){if(!current.value)return;const u=URL.createObjectURL(new Blob([current.value.content],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download=props.active.split('/').at(-1)||'script.txt';a.click();setTimeout(()=>URL.revokeObjectURL(u),100)}
onMounted(()=>{if(props.importRequest)chooseImport()});
watch(()=>props.createRequest,v=>{if(v)openNew()},{immediate:true});watch(()=>props.importRequest,v=>{if(v)chooseImport()});
</script>
<style scoped>
.jp-script-files{height:100%;min-height:0;display:flex;flex-direction:column;background:var(--ks-bg-surface);font-size:12px}.jp-script-toolbar{height:46px;display:flex;align-items:center;gap:10px;padding:0 12px;border-bottom:1px solid var(--ks-border-default);flex-shrink:0}.jp-script-toolbar>span:not(.jp-eyebrow):not(.jp-grow){font-size:10px;color:var(--ks-text-secondary)}.jp-file-input{display:none}.jp-script-body{flex:1;min-height:0;display:grid;grid-template-columns:190px minmax(0,1fr)}.jp-script-tree{padding:12px 8px;overflow:auto;border-right:1px solid var(--ks-border-default);display:flex;flex-direction:column;gap:5px}.jp-script-tree>.kel-input{margin:0 3px 8px;width:calc(100% - 6px);font-size:11px}.jp-script-tree>button{display:flex;align-items:center;gap:7px;border:0;border-radius:4px;padding:10px 7px;background:none;color:var(--ks-text-secondary);font-size:10px;overflow-wrap:anywhere;text-align:left}.jp-script-tree>button.active{background:var(--ks-bg-tag);color:var(--jp-accent)}.jp-script-tree>button>span:not(.material-design-icon){flex:1;min-width:0}.jp-script-tree small{font-size:8px;display:block;color:var(--ks-text-secondary);margin-top:3px}.jp-script-tree>button>i{height:5px;width:5px;border-radius:50%;background:var(--ks-text-warning)}.jp-files-scope{padding:12px 7px;line-height:1.8;margin-top:auto}.jp-script-workspace{min-width:0;min-height:0;display:flex;flex-direction:column}.jp-script-filebar{min-height:54px;padding:8px 12px;display:flex;align-items:center;gap:7px;border-bottom:1px solid var(--ks-border-default);flex-wrap:wrap}.jp-script-filebar>div{min-width:110px}.jp-script-filebar code{font-size:11px;display:block}.jp-script-dirty{display:block;font-size:8px;color:var(--ks-text-warning);margin-top:3px}.jp-script-dirty.saved{color:var(--ks-text-secondary)}.jp-script-workspace :deep(.jp-script-code){flex:1;min-height:0}.jp-script-workspace>footer{display:flex;align-items:center;gap:12px;padding:7px 12px;border-top:1px solid var(--ks-border-default);font-size:9px;color:var(--ks-text-secondary);flex-wrap:wrap}.jp-script-loading{padding:40px;color:var(--ks-text-secondary);font-size:11px}.jp-script-alert{padding:9px 12px;background:var(--ks-bg-error);color:var(--ks-text-error);font-size:11px;display:flex;justify-content:space-between}.jp-script-alert>button{border:0;background:none;color:inherit}.jp-script-dialog{padding:22px 24px}.jp-script-dialog>label{display:flex;flex-direction:column;gap:7px;font-size:11px;color:var(--ks-text-secondary);margin:16px 0}.jp-script-dialog select,.jp-import-list input{font-size:12px;padding:8px;border:1px solid var(--ks-border-default);border-radius:5px;background:var(--ks-bg-input);color:var(--ks-text-primary)}.jp-script-dialog p{font-size:11px;line-height:1.9;color:var(--ks-text-secondary)}.jp-script-dialog code{font-size:11px}.jp-script-dialog .jp-error{color:var(--ks-text-error)}.jp-script-dialog .jp-wizard-footer{justify-content:flex-end}.jp-import-list{border:1px solid var(--ks-border-default);border-radius:5px}.jp-import-list label{display:flex;align-items:center;gap:10px;padding:12px}.jp-import-list label>span:not(.material-design-icon){flex:1;font-size:11px}.jp-import-list small{display:block;color:var(--ks-text-secondary);font-size:9px}.jp-import-list input{max-width:200px}.jp-script-boundary{border:1px solid var(--ks-border-default);border-radius:4px;background:var(--ks-bg-base);padding:10px}
@media(max-width:1200px){.jp-script-body{grid-template-columns:150px minmax(0,1fr)}}
</style>
